INSERT INTO project_templates (id, name, description, kind, body, created_by) VALUES (1, 'Erasmus+ KA220 cooperation partnership (24 months)', 'Standard KA2 skeleton: five work packages, research → main output → pilots, interim report at M12, final at M24. Due dates are project months.', 'eu', '{"sections":[{"name":"WP1 — Management"},{"name":"WP2 — Research"},{"name":"WP3 — Main output"},{"name":"WP4 — Pilots"},{"name":"WP5 — Dissemination"}],"labels":[{"name":"partner-input","color":"#0ea5e9"},{"name":"deliverable","color":"#9333ea"}],"custom_fields":[{"name":"Lead partner","type":"text"},{"name":"Dissemination level","type":"select","options":[{"key":"pu","label":"Public"},{"key":"se","label":"Sensitive"}]}],"tasks":[{"key":"kickoff","title":"Kick-off meeting","section":"WP1 — Management","due_month":1,"is_milestone":true,"assign":"creator","checklist":["Agenda","Partner presentations","Minutes and decisions"]},{"key":"qa-plan","title":"Quality assurance plan","section":"WP1 — Management","due_month":3,"labels":["deliverable"],"blocked_by":["kickoff"]},{"key":"dmp","title":"Dissemination & exploitation plan","section":"WP5 — Dissemination","due_month":3,"labels":["deliverable"],"blocked_by":["kickoff"]},{"key":"research","title":"Comparative research report","section":"WP2 — Research","start_month":2,"due_month":6,"labels":["deliverable","partner-input"],"subtasks":[{"key":"desk","title":"Desk research per country","due_month":4,"labels":["partner-input"]},{"key":"fg","title":"Focus groups per country","due_month":5,"labels":["partner-input"]},{"key":"synth","title":"Synthesis report","due_month":6,"blocked_by":["desk","fg"]}]},{"key":"interim","title":"Interim report to the National Agency","section":"WP1 — Management","due_month":12,"labels":["partner-input"],"checklist":["Narrative per WP","Timesheets","Dissemination evidence","Financial statement"]},{"key":"output","title":"Main result (toolkit / curriculum / platform)","section":"WP3 — Main output","start_month":6,"due_month":14,"labels":["deliverable"],"blocked_by":["research"]},{"key":"pilot","title":"Pilots in each country","section":"WP4 — Pilots","start_month":15,"due_month":18,"blocked_by":["output"]},{"key":"me","title":"Multiplier events","section":"WP5 — Dissemination","due_month":22},{"key":"final","title":"Final report","section":"WP1 — Management","due_month":24,"is_milestone":true,"blocked_by":["pilot"]}]}', 3);
